import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_INT = Integer.MAX_VALUE;

    static class Edge {
        int v, p, capacity, weight;
        Edge(int v, int p, int capacity, int weight) {
            this.v = v;
            this.p = p;
            this.capacity = capacity;
            this.weight = weight;
        }
    }

    static class FlowAlgorithm {
        static final int MAX_NODES = 10001;
        List<Edge>[] adj = new ArrayList[MAX_NODES];
        int[] visited = new int[MAX_NODES];
        int[] current = new int[MAX_NODES];
        int total_nodes;
        int[] dist = new int[MAX_NODES];
        int[] potential = new int[MAX_NODES];

        FlowAlgorithm() {
            for (int i = 0; i < MAX_NODES; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        int createVertices(int count) {
            int start = total_nodes;
            for (int i = 0; i < count; i++) {
                adj[total_nodes++].clear();
            }
            return start;
        }

        void addEdge(int u, int v, int cap, int w) {
            adj[u].add(new Edge(v, adj[v].size(), cap, w));
            adj[v].add(new Edge(u, adj[u].size() - 1, 0, -w));
        }

        boolean findShortestPath(int s, int t) {
            Arrays.fill(dist, 0, total_nodes, MAX_INT);
            Arrays.fill(visited, 0, total_nodes, 0);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[s] = 0;
            pq.offer(new int[]{0, s});
            while (!pq.isEmpty()) {
                int[] du = pq.poll();
                int u = du[1], duDist = du[0];
                if (visited[u] != 0) continue;
                visited[u] = 1;
                for (Edge e : adj[u]) {
                    int v = e.v;
                    int dv = duDist + potential[u] + e.weight - potential[v];
                    if (e.capacity == 0 || visited[v] != 0 || dist[v] <= dv) continue;
                    dist[v] = dv;
                    pq.offer(new int[]{dist[v], v});
                }
            }
            return visited[t] != 0;
        }

        boolean buildLevelGraph(int s, int t) {
            Arrays.fill(visited, 0, total_nodes, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : adj[u]) {
                    int v = e.v;
                    if (visited[v] != 0 || e.capacity == 0) continue;
                    if (dist[v] != dist[u] + e.weight - potential[v] + potential[u]) continue;
                    visited[v] = visited[u] + 1;
                    q.offer(v);
                }
            }
            return visited[t] != 0;
        }

        int sendFlow(int u, int t, int flow) {
            if (u == t) return flow;
            int totalSent = 0;
            for (int i = current[u]; i < adj[u].size(); i++) {
                Edge e = adj[u].get(i);
                int v = e.v;
                if (e.capacity == 0 || visited[v] != visited[u] + 1) continue;
                if (dist[v] != dist[u] + e.weight - potential[v] + potential[u]) continue;
                int pushed = sendFlow(v, t, Math.min(e.capacity, flow));
                totalSent += pushed;
                flow -= pushed;
                e.capacity -= pushed;
                adj[v].get(e.p).capacity += pushed;
                if (flow == 0) break;
                current[u]++;
            }
            return totalSent;
        }

        int[] maxFlowCost(int s, int t, int maxFlow) {
            int totalFlow = 0, totalCost = 0;
            Arrays.fill(potential, 0, total_nodes, 0);
            while (findShortestPath(s, t)) {
                int flow = 0;
                while (buildLevelGraph(s, t)) {
                    Arrays.fill(current, 0, total_nodes, 0);
                    int pushedFlow = sendFlow(s, t, maxFlow);
                    maxFlow -= pushedFlow;
                    flow += pushedFlow;
                    if (maxFlow == 0) break;
                }
                totalFlow += flow;
                totalCost += (dist[t] + potential[t]) * flow;
                for (int i = 0; i < total_nodes; i++) {
                    potential[i] += dist[i];
                }
                if (maxFlow == 0) break;
            }
            return new int[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int totalVertices = Math.max(n, k) * 2;
        FlowAlgorithm flow = new FlowAlgorithm();
        int s = flow.createVertices(1);
        int t = flow.createVertices(1);

        st = new StringTokenizer(br.readLine());
        for (int j = 0; j < k; j++) {
            int a = Integer.parseInt(st.nextToken());
            a--;
            flow.addEdge(s, a, 1, 0);
        }

        for (int z = 1; z <= m; z++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int i = 0; i + 1 < totalVertices; i++) {
                int u1 = u + i * n;
                int v1 = v + (i + 1) * n;
                int u2 = u + (i + 1) * n;
                int v2 = v + i * n;
                for (int j = 0; j < k; j++) {
                    flow.addEdge(u1, v1, 1, c + d * (2 * j + 1));
                    flow.addEdge(v2, u2, 1, c + d * (2 * j + 1));
                }
            }
        }

        for (int i = 0; i + 1 < totalVertices; i++) {
            for (int j = 0; j < n; j++) {
                int u = j + i * n;
                int v = j + (i + 1) * n;
                flow.addEdge(u, v, MAX_INT, c);
            }
        }

        for (int i = 0; i < totalVertices; i++) {
            flow.addEdge(i * n, t, MAX_INT, 0);
        }

        int[] result = flow.maxFlowCost(s, t, MAX_INT);
        System.out.println(result[1]);
    }
}
